import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Security and secrets","description":"","frontmatter":{},"headers":[],"relativePath":"en/operations/security.md","filePath":"en/operations/security.md","lastUpdated":1794405696000}`),a={name:`en/operations/security.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="security-and-secrets" tabindex="-1">Security and secrets <a class="header-anchor" href="#security-and-secrets" aria-label="Permalink to “Security and secrets”">​</a></h1><h2 id="tell-the-keys-apart" tabindex="-1">Tell the keys apart <a class="header-anchor" href="#tell-the-keys-apart" aria-label="Permalink to “Tell the keys apart”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Purpose</th><th>Where it is stored</th></tr></thead><tbody><tr><td>CLOUDFLARE_API_TOKEN</td><td>Operations such as deployment, D1 and Access</td><td>Secrets management of your workstation or CI</td></tr><tr><td>JEV_KEYRING</td><td>Encrypting and decrypting site-only API keys</td><td>A runtime secret for the Worker or Node.js</td></tr><tr><td>ADMIN_TOKEN</td><td>The first superuser registration in production</td><td>A runtime secret. Not used for normal sign-in after the first time</td></tr><tr><td>AUTH_SECRET</td><td>Signing diagnostic authorization</td><td>An independent runtime secret for each environment</td></tr></tbody></table><p><strong>The token for operating Cloudflare, the encryption key and each site&#39;s Jev API key are all separate.</strong> Don&#39;t put the values in Git, HTML, JavaScript, plain variables or Issues. The admin console doesn&#39;t show the values either.</p><p>On Cloudflare, register JEV_KEYRING and AUTH_SECRET as <strong>secrets</strong>, not as ordinary text variables. Jev API keys are entered in each site&#39;s admin console. If you display the whole configuration through the API, plaintext variables may appear in the output. Limit your checks to names, types and similar.</p><p>A site-only Jev API key is saved <a href="./jev-keys">encrypted in a dedicated table</a> and decrypted with the runtime secret <code>JEV_KEYRING</code>. There is no API that shows a key again. Only site admins and superusers handle settings and usage records. Rotate it independently of AUTH_SECRET.</p><h2 id="passkeys-and-admin-sessions" tabindex="-1">Passkeys and admin sessions <a class="header-anchor" href="#passkeys-and-admin-sessions" aria-label="Permalink to “Passkeys and admin sessions”">​</a></h2><p>The admin cookie is Secure, HttpOnly and SameSite=Lax, and is never placed in the browser&#39;s Web Storage or in a URL. The server keeps a hash of a random session value.</p><p>Writes verify the origin and CSRF, and the server also checks site permissions. Disabling a user or changing a permission is applied in the API, not just hidden on the screen.</p><h2 id="protecting-preview" tabindex="-1">Protecting Preview <a class="header-anchor" href="#protecting-preview" aria-label="Permalink to “Protecting Preview”">​</a></h2><p>A Preview URL is public by default. Limit access to your team with Cloudflare Access, and have the Worker also verify the Access JWT. Keep D1, secrets and the cost counter separate from production.</p><p>The permissions of the API token used to configure Access do not automatically grant the signed-in user any JevSense permissions.</p><h2 id="custom-code" tabindex="-1">Custom code <a class="header-anchor" href="#custom-code" aria-label="Permalink to “Custom code”">​</a></h2><p>It runs with the same privileges as your site. Limit who can register code to admins, and review and check it. variables are also visible in the browser.</p><h2 id="external-sending-and-logs" tabindex="-1">External sending and logs <a class="header-anchor" href="#external-sending-and-logs" aria-label="Permalink to “External sending and logs”">​</a></h2><p>Check the target pages&#39; metadata, URL paths and optional integrations, and put consent and a privacy notice in place. Check Jev&#39;s retention terms, pricing and so on with the provider.</p><p>Make sure proxies and APM don&#39;t record request bodies, cookies, Authorization, diagnostic authorization or browsing history. A CORS origin can usually be spoofed by an ordinary HTTP client, so don&#39;t rely on it as authentication against cost attacks.</p><p>Only the start, result, model, latency and key type of real Jev calls are stored in the <a href="./../guides/jev">usage records</a>. State, questions, answers and visitor information are not recorded. An interruption between the start and saving the result is recorded as &quot;unconfirmed&quot; and is not used as the basis for a billed amount.</p><h2 id="cost-and-availability" tabindex="-1">Cost and availability <a class="header-anchor" href="#cost-and-availability" aria-label="Permalink to “Cost and availability”">​</a></h2><p>Set a daily limit and a concurrency limit. Failed real-model requests also count toward the daily limit, and there is no automatic retry. The in-app limits alone don&#39;t guarantee a strict cap on what you are billed.</p><p>The IP limit on Workers is an approximate limit per location. The Node.js counter lives in the process and resets on restart.</p><h2 id="if-you-suspect-a-leak" tabindex="-1">If you suspect a leak <a class="header-anchor" href="#if-you-suspect-a-leak" aria-label="Permalink to “If you suspect a leak”">​</a></h2><p>Reissue or revoke the key with the relevant provider, and update the secret in every environment that uses it. For authentication problems, also disable users and end sessions.</p><p>Changing AUTH_SECRET invalidates diagnostic authorization, but that alone doesn&#39;t end every database-backed admin session. Revoke sessions explicitly if needed.</p><h2 id="checking-page-information-fetching" tabindex="-1">Checking page information fetching <a class="header-anchor" href="#checking-page-information-fetching" aria-label="Permalink to “Checking page information fetching”">​</a></h2><p>The authority for a fetching check is limited to the administrator&#39;s sign-in, the site, and the page&#39;s origin and path. A connection can be started only once, and it expires in 5 minutes. The string that carries the authority is not placed in a URL, and the admin console and the target page verify the sender when handing it over. After sign-out or a permission change, no new connection can be made. A check already connected also ends on the end operation, consent withdrawal, a URL change or expiry.</p><p>The server keeps a hash of the short-lived checking authority and the draft settings. The full HTML of the real page, the whole JSON-LD and the fetched result are not stored, and the check result goes directly from the target page to the admin console. The admin console also validates it as untrusted input and shows it as text. Don&#39;t include secrets in the keys, conditions or prefixes you set.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};